// Writes db/migrations/001_county_codes.sql from county-codes.js
const fs = require('fs'), path = require('path');
const { rows } = require('./county-codes.js');
const vals = rows.map((r) => `  (${r.co_no}, '${r.name.replace(/'/g, "''")}', '${r.fips}')`).join(',\n');
const sql = `-- DOR county numbers (match NAL<co_no>F....csv), parcels.county names, and FIPS.
-- Generated by scripts/parcels-v2/gen-001.js from county-codes.js (cross-checked against NAL filenames).
CREATE TABLE IF NOT EXISTS county_codes (
  co_no smallint PRIMARY KEY,
  name  text     NOT NULL UNIQUE,
  fips  char(5)  NOT NULL UNIQUE
);

INSERT INTO county_codes (co_no, name, fips) VALUES
${vals}
ON CONFLICT (co_no) DO NOTHING;
`;
fs.mkdirSync(path.join(__dirname, '..', '..', 'db', 'migrations'), { recursive: true });
fs.writeFileSync(path.join(__dirname, '..', '..', 'db', 'migrations', '001_county_codes.sql'), sql);
console.log('wrote 001 with', rows.length, 'rows');
